package com.urlshortener.controller;import com.urlshortener.dto.CreateShortUrlRequest;import com.urlshortener.dto.CreateShortUrlResponse;import com.urlshortener.model.Url;import com.urlshortener.service.UrlService;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springframework.http.HttpHeaders;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import java.net.URI;@RestController@RequestMapping("/api/v1")public class UrlShorteningController {private final UrlService urlService;public UrlShorteningController(UrlService urlService) {this.urlService = urlService;}@PostMapping("/shorten")public ResponseEntity<CreateShortUrlResponse> createShortUrl(@Valid @RequestBody CreateShortUrlRequest request, HttpServletRequest httpServletRequest) {Url url = urlService.generateShortUrl(request.getLongUrl());String baseUrl = getBaseUrl(httpServletRequest);String shortUrl = baseUrl + url.getShortCode();CreateShortUrlResponse response = new CreateShortUrlResponse(url.getLongUrl(), shortUrl, url.getShortCode());return new ResponseEntity<>(response, HttpStatus.CREATED);}@GetMapping("/{shortCode}")public ResponseEntity<Void> redirectToLongUrl(@PathVariable String shortCode) {String longUrl = urlService.getLongUrl(shortCode);HttpHeaders headers = new HttpHeaders();headers.setLocation(URI.create(longUrl));return new ResponseEntity<>(headers, HttpStatus.FOUND);}private String getBaseUrl(HttpServletRequest request) {String scheme = request.getScheme();String serverName = request.getServerName();int serverPort = request.getServerPort();String contextPath = request.getContextPath();StringBuilder url = new StringBuilder();url.append(scheme).append("://").append(serverName);if (serverPort != 80 && serverPort != 443) {url.append(":").append(serverPort);}url.append(contextPath).append("/");return url.toString();}}